INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66461702', 66461702, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Pemeliharaan Videotron pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 2500000000, 'January 2026', 'APBN - PNBP (D)', 1, 1, '1.0 Thn', 'Melakukan pemeliharaan menyeluruh terhadap unit Videotron di Tempat Pemeriksaan Imigrasi guna memastikan penyampaian informasi dan edukasi layanan keimigrasian kepada WNI/WNA berjalan optimal. Lingkup pekerjaan mencakup perawatan preventif (rutin), korektif (perbaikan kerusakan), prediktif (analisis potensi kerusakan), pengelolaan sistem konten, serta pelaporan berkala untuk menjaga uptime dan kualitas tampilan layar.', '1. Preventif: Pemeriksaan fisik (modul LED, rangka, kabel), pembersihan layar dari debu/korosi, kalibrasi warna/kecerahan, dan pengujian fungsi software/firmware. 2. Korektif: Perbaikan/penggantian modul LED mati (dead pixel), power supply, kontroler, serta penanganan masalah visual (flickering/garis). 3. Prediktif: Pemantauan kinerja real-time dan analisis data untuk mendeteksi potensi kerusakan dini. 4. Sistem & Konten: Pemeliharaan server pengendali, backup data konten, dan pembaruan (update) sistem keamanan. 5. Administrasi: Dokumentasi kegiatan dan pelaporan kerusakan serta riwayat pemeliharaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2751302);
