INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66462413', 66462413, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Tenaga Alih Daya Administrasi, Keuangan dan Anggaran (PAKK Tahun 2026)', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 360000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 Paket', '1. Mendukung kelancaran pelaksanaan administrasi kegiatan dan penyampaian data anggaran secara administratif di lingkungan PAKK agar berjalan tertib, tepat waktu, dan sesuai ketentuan yang berlaku. 2. Meningkatkan efisiensi operasional PAKK melalui koordinasi yang efektif, baik secara internal maupun dengan unit kerja lain di lingkungan Bappenas 3. Membantu pelaksanaan tugas kesekretariatan pimpinan secara efektif dan berkesinambungan.', '1. Pemantauan realisasi penggunaan anggaran PAKK secara berkala dan menyusun catatan perkembangan serapan anggaran PAKK 2. Memberikan dukungan manajemen internal dalam seluruh tahapan perencanaan, pelaksanaan, pengendalian, dan pelaporan kegiatan Pusat Analisis Kebijakan dan Kinerja, termasuk penyiapan bahan administrasi pendukung, pengelolaan dokumen perencanaan dan pelaksanaan kegiatan, serta penyusunan data dan informasi administratif yang dibutuhkan guna mendukung efektivitas dan efisiensi penyelenggaraan tugas unit kerja. 3. Memberikan dukungan administrasi kegiatan di Unit Kerja Pusat Analisis Kebijakan dan Kinerja sebagai tenaga pendukung, meliputi membantu penyiapan jadwal kegiatan, membantu penyusunan dan pendistribusian undangan internal, menyiapkan daftar hadir dan kelengkapan administrasi kegiatan, membantu pencatatan hasil kegiatan secara administratif, serta membantu pengumpulan dan penataan dokumen kegiatan berdasarkan arahan pejabat atau pegawai yang berwenang.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2751705);
