INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66430888', 66430888, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Balai Monitor Spektrum Frekuensi Radio Kelas II Lampung', 'Tenaga Pendukung Administrasi dan Teknis Perorangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'Lampung, Lampung Selatan (Kab.)', 274000000, 'January 2026', 'APBN - RUPIAH MURNI PENDAMPING (C)', 1, 1, '5 Orang', '3 Orang tenaga pendukung administrasi 1 Orang tenaga pendukung pembuat konten digital 1 orang tenaga pendukun pengolah data', '1️⃣ Administrasi – jasa dukungan administrasi untuk kegiatan monitoring dan penertiban spektrum frekuensi radio, yang meliputi antara lain: a. dukungan administrasi pengelolaan dokumen kegiatan monitoring dan penertiban spektrum frekuensi radio; b. pengarsipan dan penataan dokumen hasil kegiatan monitoring dan penertiban; c. penginputan data administratif non-verifikatif sesuai dokumen sumber; d. penyusunan rekapitulasi administrasi kegiatan monitoring dan penertiban per periode; e. penyusunan laporan dukungan administrasi kegiatan monitoring dan penertiban spektrum frekuensi radio. Ruang lingkup jasa ini tidak mencakup kewenangan teknis pengawasan, penilaian pelanggaran, penetapan hasil penertiban, maupun pengambilan keputusan. ________________________________________ 2️⃣ Administrasi – jasa dukungan administrasi untuk kegiatan pelayanan, konsultasi, dan asistensi perizinan Izin Stasiun Radio (ISR), yang meliputi antara lain: a. dukungan administrasi pengelolaan berkas pelayanan perizinan ISR; b. pengarsipan dokumen permohonan dan korespondensi perizinan ISR; c. penginputan data administratif non-verifikatif permohonan perizinan sesuai dokumen yang diterima; d. penyusunan rekapitulasi administrasi permohonan perizinan ISR; e. penyusunan laporan dukungan administrasi pelayanan perizinan ISR. Ruang lingkup jasa ini tidak mencakup verifikasi substansi perizinan, pemberian rekomendasi teknis, penetapan izin, maupun kewenangan pelayanan yang bersifat keputusan. ________________________________________ 3️⃣ Administrasi – jasa dukungan administrasi untuk kegiatan Bagian Umum/Tata Usaha, yang meliputi antara lain: a. dukungan administrasi pengelolaan surat-menyurat dan dokumen perkantoran; b. pengarsipan dokumen administrasi umum dan tata usaha; c. penginputan data administratif kegiatan perkantoran; d. penyusunan rekapitulasi administrasi kegiatan umum dan tata usaha; e. penyusunan laporan dukungan administrasi Bagian Umum/Tata Usaha. Ruang lingkup jasa ini tidak mencakup pengelolaan kepegawaian, pengambilan keputusan administratif, penandatanganan dokumen resmi, maupun kewenangan manajerial. ________________________________________ 4️⃣ Konten Kreator – jasa pembuatan dan pengelolaan konten informasi untuk mendukung publikasi seluruh kegiatan Balai Monitor Spektrum Frekuensi Radio Kelas II Lampung, yang meliputi antara lain: a. penyusunan konten informasi kegiatan monitoring, penertiban, pelayanan perizinan, dan kegiatan pendukung lainnya; b. pengolahan materi visual dan teks sederhana untuk publikasi; c. pengunggahan konten pada media resmi instansi; d. pengarsipan konten dan dokumentasi kegiatan; e. penyusunan laporan dokumentasi dan publikasi kegiatan. Ruang lingkup jasa ini tidak mencakup penetapan kebijakan komunikasi, penyampaian pernyataan resmi instansi, maupun kewenangan kehumasan strategis. ________________________________________ 5️⃣ Pengolah Data – jasa dukungan pengolahan data untuk mendukung seluruh kegiatan Balai Monitor Spektrum Frekuensi Radio, dengan fokus utama pada kegiatan pengukuran kualitas layanan infrastruktur digital (seluler), yang meliputi antara lain: a. pengolahan data hasil kegiatan pengukuran kualitas layanan infrastruktur digital secara deskriptif; b. penyusunan tabel, grafik, dan rekap data hasil pengukuran; c. pengelolaan basis data sederhana pendukung kegiatan pengukuran dan kegiatan lainnya; d. penyusunan laporan pengolahan data deskriptif; e. dukungan pengolahan data administratif untuk kegiatan lain sesuai kebutuhan unit kerja. Ruang lingkup jasa ini tidak mencakup analisis kebijakan, penilaian kualitas layanan secara normatif, penetapan hasil pengukuran, maupun pemberian rekomendasi keputusan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2758798);
