INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66429819', 66429819, 'analyze_legacy', 'Kab. Gresik', 'kabkota', 'RSUD IBNU SINA', 'BELANJA MODAL ALAT KEDOKTERAN GIGI (AEROSOL SUCTION GIGI)', 'Barang', 'E-Purchasing', 'Jawa Timur, Gresik (Kab.)', 48000000, 'March 2026', 'BLUD', 1, 1, '2 UNIT', 'BELANJA MODAL ALAT KEDOKTERAN GIGI (AEROSOL SUCTION GIGI)', '1. Sistem Penyaringan - Menggunakan sistem filtrasi multi-layer. - Dilengkapi HEPA Filter dengan efisiensi penyaringan minimal 99,97% untuk partikel ≥0,3 mikron. - Dilengkapi pre-filter untuk penyaringan partikel kasar. - Dilengkapi filter karbon aktif (activated carbon) atau setara untuk mengurangi bau dan gas. 2. Kapasitas Hisap (Air Flow Rate) - Kapasitas aliran udara minimal ≥ 300 m³/jam atau setara. 3. Tingkat Kebisingan - Tingkat kebisingan maksimal ≤ 65 dB pada penggunaan normal. 4. Lengan Hisap (Suction Arm) - Dilengkapi lengan fleksibel yang dapat diposisikan sesuai kebutuhan operator. - Panjang lengan minimal 80 cm atau lebih. - Kepala suction dapat diarahkan dan diposisikan dekat area kerja pasien. 5. Sistem Operasional - Dilengkapi panel kontrol digital atau manual. - Memiliki pengaturan kecepatan hisap (multi speed). - Dilengkapi indikator kondisi filter atau pengingat penggantian filter (apabila tersedia). 6. Desain dan Mobilitas - Desain portable atau mobile. - Dilengkapi roda (caster wheel) dengan sistem pengunci untuk memudahkan pemindahan alat. 7. Aksesori Standar - Lengan suction fleksibel. - Kepala suction. - Pre-filter. - HEPA filter. - Filter karbon aktif atau setara.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2759021);
